insert into public.meal_plan_library_items (id, plan_id, day_type, meal_type, position, recipe_id, servings)
select md5('unfnshd-meal-library:' || ((p->>'s') || ':' || r.day_type || ':' || r.meal_type))::uuid, md5('unfnshd-meal-library:' || (p->>'s'))::uuid, r.day_type, r.meal_type,
